parser MyParser(packet_in pkt, out headers_t hdr,
                inout meta_t meta, inout standard_metadata_t sm) {
    state start {
        pkt.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            0x0800: parse_ipv4;
            default: accept;
        }
    }
    state parse_ipv4 { pkt.extract(hdr.ipv4); transition accept; }
}

table ipv4_lpm {
    key = { hdr.ipv4.dstAddr : lpm; }
    actions = { forward; drop; }
    size = 1024;
    default_action = drop();
}

for each active queue i in round-robin order:
  deficit[i] += quantum[i]
  while queue i not empty and head(i).size <= deficit[i]:
    deficit[i] -= head(i).size; send(dequeue(i))
  if queue i empty: deficit[i] = 0
